with filtered as (select *, substring(status, 1, 3) status_prefix, cast(cost as int) cost_int, coalesce(carrier, 'DIRECT') carrier_clean from shipments where shipped_date > date '2023-12-08') select *, ntile(4) over (partition by carrier order by cost_int asc, id asc) cost_int_bucket, ntile(5) over (partition by order_id order by cost desc, id asc) cost_bucket, dense_rank() over w_recent cost_int_dense_rank from filtered window w_recent as (partition by carrier order by cost_int desc);
